(()=>{'use strict';const kinds={hit:'Big hit',entry:'Đủ chuỗi',win:'Thắng',loss:'Thua',step:'Tăng bậc',error:'Lỗi / mất kết nối',startStop:'Bắt đầu / dừng',round:'Trạng thái mỗi vòng'};let templates={};const defaults=Object.fromEntries(Object.keys(kinds).map(k=>[k,'{message}']));let attached=false;function el(tag,txt){const e=document.createElement(tag);if(txt)e.textContent=txt;return e}function render(){if(attached&&!document.getElementById("slide-template-editor"))attached=false;if(attached)return;const header=[...document.querySelectorAll('h2,h3')].find(e=>e.textContent?.trim()==='Tín hiệu / Telegram');if(!header)return;const section=header.closest('.row')?.nextElementSibling||header.parentElement;const panel=el('section');panel.id='slide-template-editor';panel.style.cssText='margin:12px 0;padding:12px;border:1px solid #3c5871;border-radius:8px;background:#12283b;color:#eee;';const title=el('h3','CHỈNH SỬA MẪU TIN NHẮN');panel.append(title);const help=el('p','Biến: {message} {kind} {time} {result} {round}. Khi không có dữ liệu, giá trị hiển thị —. Chỉ thay đổi tin Telegram, không điều khiển cược.');help.style.fontSize='11px';panel.append(help);const label=el('label','Loại thông báo');const select=el('select');for(const [id,name] of Object.entries(kinds)){const opt=el('option',name);opt.value=id;select.append(opt)}label.append(select);panel.append(label);const inputLabel=el('label','Nội dung mẫu');const input=el('textarea');input.rows=5;input.maxLength=1000;input.style.cssText='width:100%;box-sizing:border-box;min-height:90px;padding:8px;background:#172d42;color:#fff;border:1px solid #47617b;border-radius:5px;';inputLabel.append(input);panel.append(inputLabel);const preview=el('pre');preview.style.cssText='white-space:pre-wrap;word-break:break-word;background:#0c1b29;padding:10px;border-radius:5px;font-size:12px;';panel.append(el('h4','Xem trước'),preview);const status=el('p');status.style.fontSize='12px';const save=el('button','Lưu mẫu');const reset=el('button','Khôi phục mặc định');reset.style.marginLeft='8px';panel.append(save,reset,status);function update(){const sample={message:'💰 [STAKE] R123 · x2.26 · số dư 132.91',kind:select.value,time:new Date().toLocaleString('vi-VN'),result:'2.26',round:'123'};preview.textContent=input.value.replace(/\{(message|kind|time|result|round)\}/g,(m,key)=>sample[key]);}function choose(){input.value=templates[select.value]??'{message}';update()}select.addEventListener('change',choose);input.addEventListener('input',update);save.addEventListener('click',async()=>{try{templates[select.value]=input.value;const r=await chrome.runtime.sendMessage({type:'telegram-templates-save',templates});status.textContent=r.ok?'Đã lưu mẫu tin nhắn':(r.error||'Lỗi lưu mẫu')}catch{status.textContent='Không kết nối được extension'}});reset.addEventListener('click',()=>{input.value='{message}';update()});section?.after(panel);attached=true;chrome.runtime.sendMessage({type:'telegram-templates-get'}).then(r=>{templates={...defaults,...(r.templates||{})};choose()}).catch(()=>{templates={...defaults};choose()});}const observer=new MutationObserver(render);observer.observe(document.documentElement,{childList:true,subtree:true});render();})();